<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/functions.php';$pdo=db();$category=$_GET['category']??'';$where="cr.status='active' AND cr.urgency IN ('urgent','high')";$params=[];if(in_array($category,clothing_categories(),true)){$where.=' AND EXISTS (SELECT 1 FROM request_requirements rr WHERE rr.request_id=cr.id AND rr.category=?)';$params[]=$category;}$stmt=$pdo->prepare("SELECT cr.*,c.organization_name,COALESCE((SELECT SUM(quantity_needed) FROM request_requirements WHERE request_id=cr.id),0) needed,COALESCE((SELECT SUM(di.quantity) FROM donation_items di JOIN donation_pledges dp ON dp.id=di.pledge_id JOIN request_requirements rr ON rr.id=di.request_requirement_id WHERE rr.request_id=cr.id AND dp.status='received'),0) received FROM clothing_requests cr JOIN charities c ON c.id=cr.charity_id WHERE $where ORDER BY FIELD(cr.urgency,'urgent','high'),cr.created_at DESC");$stmt->execute($params);$requests=$stmt->fetchAll();$pageTitle='Urgent clothing needs';require __DIR__ . '/../includes/header.php'; ?>
<section class="page-hero"><div class="shell"><span class="eyebrow" style="color:#FFD928">Needs that cannot wait</span><h1>Urgent clothing needs.</h1><p>These charities have flagged a time-sensitive shortage. Choose an exact size and make a pledge that can move quickly.</p></div></section><section class="section" style="padding-top:30px"><div class="shell"><form class="filter-card" style="margin:0 0 24px" method="get"><div class="filters" style="grid-template-columns:1fr auto"><select class="select" name="category"><option value="">All clothing categories</option><?php foreach(clothing_categories() as $c):?><option value="<?=e($c)?>" <?=$category===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><button class="button button-small">Filter urgent needs</button></div></form><?php if(!$requests):?><div class="empty"><span class="empty-icon">✦</span>No urgent needs match that category at this moment.</div><?php else:?><div class="request-grid"><?php foreach($requests as $r):$remaining=max(0,$r['needed']-$r['received']);$progress=$r['needed']?round($r['received']/$r['needed']*100):0;?><article class="request-card" style="border-color:<?=$r['urgency']==='urgent'?'#F04427':'var(--border)'?>"><div class="card-top"><div class="category-icon"><?=request_image_markup($r['image_path'])?></div><span class="status status-warning"><?=e($r['urgency'])?></span></div><h3><?=e($r['title'])?></h3><p><?=e($r['organization_name'])?> · <?=e($r['location'])?></p><div class="progress"><span style="width:<?=$progress?>%"></span></div><div class="progress-info"><span><?=$remaining?> items still needed</span><span><?=$r['received']?>/<?=$r['needed']?></span></div><a class="button button-small" href="<?=e(url('donor/request.php?id='.$r['id']))?>">Help this need →</a></article><?php endforeach;?></div><?php endif;?></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
